// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * A thin strip above the page: an icon, one sentence, a link and an optional close button. Axes: tone (default,
 * muted), layout (center, split), dismiss (show, hide).
 */
import { type JSX } from "solid-js";
import { Block, Button, Container, Group, Inline, LinkPlain, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { cn, urlOf } from "../utils";

export type AnnouncementBarProps = {
  label: string;
  text: string;
  cta?: string;
  ctaHref?: string;
  icon?: string;
  dismissLabel: string;
  tone?: "default" | "muted";
  layout?: "center" | "split";
  dismiss?: "show" | "hide";
  badgeLabel?: string;
  badge?: "none" | "show";
  position?: "top" | "bottom";
  landmarkLabel?: string;
};

export function AnnouncementBar({
  label,
  text,
  cta,
  ctaHref,
  icon = "megaphone",
  dismissLabel,
  tone = "default",
  layout = "center",
  dismiss = "hide",
  badgeLabel,
  badge = "none",
  position = "top",
  landmarkLabel,
}: AnnouncementBarProps) {
  return (
    <Block
      tag="aside"
      class={cn(
        "w-full",
        (((position as string) === "bottom") ? "sticky bottom-0 z-40 border-t border-border" : ""),
        (
          (tone as string) === "muted" ? "bg-muted text-foreground"
          : "bg-primary text-primary-foreground"
        )
      )}
      aria-label={(landmarkLabel ?? label)}
      data-layout={layout}
      data-slot="announcement"
    >
      <Container
        class={cn(
          "mx-auto w-full max-w-6xl px-4",
          "flex items-center gap-4 py-2",
          (((layout as string) === "split") ? "justify-between" : "justify-center")
        )}
        data-slot="container"
      >
        <Group
          gap="4"
          align="center"
          class={cn(
            "min-w-0 flex-wrap",
            ((((layout as string) === "center") && ((dismiss as string) === "show")) ? "ml-auto" : "")
          )}
        >
          <LucideIcon name={icon} size={16} />
          {((badge as string) === "show") ? (
            <Inline
              class="rounded px-2 py-0 text-xs font-semibold inset-ring inset-ring-current"
              data-slot="announcement-badge"
            >
              {badgeLabel}
            </Inline>
          ) : null}
          <Text size="sm">
            {text}
          </Text>
          {cta ? (
            <LinkPlain
              href={urlOf(ctaHref)}
              class="inline-flex items-center gap-2 text-sm font-semibold underline underline-offset-4"
              data-slot="announcement-cta"
            >
              {cta}
              <LucideIcon name="arrow-right" size={16} />
            </LinkPlain>
          ) : null}
        </Group>
        {((dismiss as string) === "show") ? (
          <Button variant="ghost" size="sm" class="ml-auto shrink-0 text-current" type="button" aria-label={dismissLabel}>
            <LucideIcon name="x" size={16} />
          </Button>
        ) : null}
      </Container>
    </Block>
  );
}
